import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ── Tag validation ───────────────────────────────────────────────────────────

class TestTagValidation:
    @pytest.mark.parametrize("name,expected", [
        ("work", "work"),
        ("  Work  ", "work"),
        ("my-tag", "my-tag"),
        ("my_tag", "my_tag"),
        ("abc123", "abc123"),
        ("a", "a"),
        ("a" * 32, "a" * 32),
    ])
    def test_valid_names(self, name, expected):
        assert Tag(name).name == expected

    @pytest.mark.parametrize("name", [
        "",
        "   ",
    ])
    def test_empty_name(self, name):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag(name)

    def test_too_long_name(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    @pytest.mark.parametrize("name", [
        "has space",
        "has.dot",
        "has@at",
        "has!bang",
    ])
    def test_illegal_characters(self, name):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(name)

    def test_non_string(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)


# ── Enum values ──────────────────────────────────────────────────────────────

class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING == "pending"
        assert TaskStatus.DONE == "done"

    def test_from_value(self):
        assert TaskStatus("pending") is TaskStatus.PENDING
        assert TaskStatus("done") is TaskStatus.DONE


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW == "low"
        assert TaskPriority.MEDIUM == "medium"
        assert TaskPriority.HIGH == "high"

    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) == 0
        assert TaskPriority.order_key(TaskPriority.MEDIUM) == 1
        assert TaskPriority.order_key(TaskPriority.LOW) == 2

    def test_order_key_ordering(self):
        priorities = [TaskPriority.LOW, TaskPriority.HIGH, TaskPriority.MEDIUM]
        sorted_p = sorted(priorities, key=TaskPriority.order_key)
        assert sorted_p == [TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW]


# ── Task.is_overdue ─────────────────────────────────────────────────────────

class TestTaskIsOverdue:
    def _make_task(self, **kwargs):
        defaults = dict(id=1, title="test")
        defaults.update(kwargs)
        return Task(**defaults)

    def test_no_due_at(self):
        task = self._make_task()
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False

    def test_done_task_not_overdue(self):
        task = self._make_task(
            status=TaskStatus.DONE,
            due_at=datetime(2020, 1, 1, tzinfo=timezone.utc),
        )
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False

    def test_future_due_at(self):
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        task = self._make_task(due_at=now + timedelta(days=1))
        assert task.is_overdue(now) is False

    def test_past_due_at(self):
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        task = self._make_task(due_at=now - timedelta(days=1))
        assert task.is_overdue(now) is True

