        tags = [Tag("work"), Tag("WORK"), Tag("  work  ")]
        result = normalize_tags(tags)
        assert len(result) == 1
        assert result[0].name == "work"

    def test_string_to_tag(self):
        result = normalize_tags(["alpha", "beta"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_order_preserved(self):
        result = normalize_tags(["beta", "alpha", "gamma"])
        assert [t.name for t in result] == ["beta", "alpha", "gamma"]

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("aaa"), "bbb"])
        assert [t.name for t in result] == ["aaa", "bbb"]

    def test_empty(self):
        assert normalize_tags([]) == []
